  display: flex;
  flex-direction: column;
  gap: 5px;
}
.output ul button {
  font-size: 15px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 10px 15px;
  border-radius: 6px;
  width: 100%;
}
