  background: none;
  color: var(--text);
  border: none;
  outline: none;
  font-size: 14px;
  resize: none;
  user-select: text;
}
input::placeholder, textarea::placeholder {
  user-select: none;
}

textarea {
  width: 100%;
  background: var(--highlight);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 14px;
  padding: 10px 15px;
  margin-bottom: 10px;
}
textarea.active {
  border-color: var(--text);
}

[role=button] {
  cursor: pointer;
}

[role=button]:focus-visible, button:focus-visible, .timeLabels text:focus-visible {
  outline: 2px solid var(--link);
  outline-offset: 2px;
  border-radius: 2px;
}

button {
  font-family: "Space Mono", monospace;
  background: none;
  color: var(--text);
  border: none;
  font-size: 14px;
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 5px;
}
button:focus {
  outline: none;
}
button[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
button .icon {
  display: block;
}

.button {
  padding: 8px 10px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

.icon {
  font-family: "Material Symbols Outlined";
  font-weight: 300;
  line-height: 1;
}

main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
}

.contentWrapper {
  max-width: 1200px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
}

.top {
  display: flex;
  height: 50%; /* Fixed height to enable scrolling in children */
