}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
}
.tools.inactive {
  opacity: 0.2;
  pointer-events: none;
}

.collapseButton {
  border-left: 1px solid var(--border);
