  transition: width 0.3s ease-in-out;
  position: relative;
  flex-shrink: 0;
  padding-right: 5px; /* Prevent resizer from overlapping scrollbar */
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.resizing * {
  pointer-events: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  min-width: 220px;
  flex: 1 1 auto; /* Ensure it shrinks */
  overflow-y: auto;
  min-height: 0; /* CRITICAL: Enables scrolling inside flex item */
}

.sidebarFooter {
  padding: 15px; /* Compact padding */
  min-width: 220px;
