import {createContext, useContext, useState, ReactNode, Dispatch, SetStateAction} from 'react';
import type {File as UploadedFile} from '@google/genai/server';
import type {Timecode} from './types';
import modes from './modes';

interface AppContextType {
  vidUrl: string | null;
  setVidUrl: Dispatch<SetStateAction<string | null>>;
  videoDuration: number;
  setVideoDuration: Dispatch<SetStateAction<number>>;
  file: UploadedFile | null;
  setFile: Dispatch<SetStateAction<UploadedFile | null>>;
  mediaType: 'video' | 'audio' | null;
  setMediaType: Dispatch<SetStateAction<'video' | 'audio' | null>>;
  timecodeList: Timecode[] | null;
  setTimecodeList: Dispatch<SetStateAction<Timecode[] | null>>;
  textResponse: string | null;
  setTextResponse: Dispatch<SetStateAction<string | null>>;
  requestedTimecode: number | null;
  setRequestedTimecode: Dispatch<SetStateAction<number | null>>;
  selectedMode: string;
  setSelectedMode: Dispatch<SetStateAction<string>>;
  activeMode: string | undefined;
  setActiveMode: Dispatch<SetStateAction<string | undefined>>;
  isLoading: boolean;
  setIsLoading: Dispatch<SetStateAction<boolean>>;
  showSidebar: boolean;
  setShowSidebar: Dispatch<SetStateAction<boolean>>;
  isLoadingVideo: boolean;
  setIsLoadingVideo: Dispatch<SetStateAction<boolean>>;
  videoError: string | null;
  setVideoError: Dispatch<SetStateAction<string | null>>;
  uploadProgress: number;
  setUploadProgress: Dispatch<SetStateAction<number>>;
  uploadStatus: string;
  setUploadStatus: Dispatch<SetStateAction<string>>;
  apiError: string | null;
  setApiError: Dispatch<SetStateAction<string | null>>;
  customPrompt: string;
  setCustomPrompt: Dispatch<SetStateAction<string>>;
  chartMode: string;
  setChartMode: Dispatch<SetStateAction<string>>;
  chartPrompt: string;
  setChartPrompt: Dispatch<SetStateAction<string>>;
  chartLabel: string;
  setChartLabel: Dispatch<SetStateAction<string>>;
  activeSegmentIndex: number;
  setActiveSegmentIndex: Dispatch<SetStateAction<number>>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export function AppProvider({children}: {children?: ReactNode}) {
  const [vidUrl, setVidUrl] = useState<string | null>(null);
  const [videoDuration, setVideoDuration] = useState(0);
  const [file, setFile] = useState<UploadedFile | null>(null);
  const [mediaType, setMediaType] = useState<'video' | 'audio' | null>(null);
  const [timecodeList, setTimecodeList] = useState<Timecode[] | null>(null);
  const [textResponse, setTextResponse] = useState<string | null>(null);
  const [requestedTimecode, setRequestedTimecode] = useState<number | null>(null);
  const [selectedMode, setSelectedMode] = useState<string>(Object.keys(modes)[0]);
  const [activeMode, setActiveMode] = useState<string>();
  const [isLoading, setIsLoading] = useState(false);
  const [showSidebar, setShowSidebar] = useState(true);
  const [isLoadingVideo, setIsLoadingVideo] = useState(false);
  const [videoError, setVideoError] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState<number>(0);
  const [uploadStatus, setUploadStatus] = useState<string>('');
  const [apiError, setApiError] = useState<string | null>(null);
  const [customPrompt, setCustomPrompt] = useState('');
  const [chartMode, setChartMode] = useState<string>('Sentiment');
  const [chartPrompt, setChartPrompt] = useState('');
  const [chartLabel, setChartLabel] = useState('');
  const [activeSegmentIndex, setActiveSegmentIndex] = useState(-1);

  return (
    <AppContext.Provider
      value={{
        vidUrl, setVidUrl,
        videoDuration, setVideoDuration,
        file, setFile,
        mediaType, setMediaType,
        timecodeList, setTimecodeList,
        textResponse, setTextResponse,
        requestedTimecode, setRequestedTimecode,
        selectedMode, setSelectedMode,
        activeMode, setActiveMode,
        isLoading, setIsLoading,
        showSidebar, setShowSidebar,
        isLoadingVideo, setIsLoadingVideo,
        videoError, setVideoError,
        uploadProgress, setUploadProgress,
        uploadStatus, setUploadStatus,
        apiError, setApiError,
        customPrompt, setCustomPrompt,
        chartMode, setChartMode,
        chartPrompt, setChartPrompt,
        chartLabel, setChartLabel,
        activeSegmentIndex, setActiveSegmentIndex
      }}>
      {children}
    </AppContext.Provider>
  );
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useAppContext must be used within an AppProvider');
  }
  return context;
}

@charset "UTF-8";

/* RETRO PALETTE */
.light {
  --background: #E0E0E0; /* Light Gray */
  --surface: #FFFFFF;
  --text: #212121;
  --border: #000000;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #9E9E9E;
  --link: #1565C0;
  --tooltip-bg: #000000;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #D1C4E9;
  --shadow-color: rgba(0, 0, 0, 0.4);
}

.dark {
  --background: #212121; /* Dark Gray */
  --surface: #424242;
  --text: #EEEEEE;
  --border: #FFFFFF;
  --highlight: #000000;
  --primary: #8C9EFF;
  --secondary: #FFAB91;
  --accent: #A5D6A7;
  --track: #616161;
  --link: #90CAF9;
  --tooltip-bg: #FFFFFF;
  --tooltip-text: #000000;
  --active-item-bg: #4527A0;
  --shadow-color: rgba(0, 0, 0, 0.8);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
  /* Pixel art rendering preference */
  image-rendering: pixelated; 
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; /* Slightly larger for pixel fonts */
  background-color: var(--background);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 1px;
  line-height: 1.5;
}

li {
  list-style: none;
}

/* RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: 2px solid var(--border);
  outline: none;
  font-size: 20px; /* Larger for readability */
  resize: none;
  user-select: text;
  box-shadow: 4px 4px 0px 0px var(--shadow-color);
  transition: transform 0.1s;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.6;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 10px 15px;
  margin-bottom: 15px;
  border-radius: 0; /* Strict square corners */
}

textarea:focus, input:focus {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
}

textarea.active {
  border-color: var(--accent);
}

[role=button] {
  cursor: pointer;
}

[role=button]:focus-visible, button:focus-visible, .timeLabels text:focus-visible {
  outline: 2px dashed var(--link);
  outline-offset: 4px;
}

/* RETRO BUTTONS */
button {
  font-family: var(--font-header);
  font-size: 12px; /* Small text for headers */
  background: var(--surface);
  color: var(--text);
  border: 2px solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 4px 4px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  text-transform: uppercase;
  padding: 4px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0px 0px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
  transform: translate(2px, 2px);
  background: var(--track);
}

button .icon {
  display: block;
}

.button {
  padding: 12px 14px;
  border-radius: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: var(--surface);
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

/* MATERIAL ICONS - PIXELATED STYLE ATTEMPT */
.icon {
  font-family: "Material Symbols Outlined";
  font-weight: 400; /* Bolder */
  line-height: 1;
  font-size: 20px;
}

/* MAIN LAYOUT */
main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
  /* Retro CRT lines overlay pattern (optional, kept subtle) */
  background-image: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 0, 0, 0.05) 2px,
    rgba(0, 0, 0, 0.05) 4px
  );
}

.contentWrapper {
  max-width: 1280px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
  border-left: 4px solid var(--border);
  border-right: 4px solid var(--border);
  background: var(--background);
}

.top {
  display: flex;
  height: 50%; 
  border-bottom: 4px solid var(--border);
}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
  background-color: var(--surface);
}
.tools.inactive {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(100%);
}

.collapseButton {
  border: none;
  border-left: 4px solid var(--border);
  width: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary);
  color: #FFF;
  box-shadow: none;
}
.collapseButton:active {
    transform: none;
}
.collapseButton .icon {
  font-size: 24px;
  color: #FFF;
}

.modeSelector {
  display: flex;
  flex-direction: column;
  gap: 0; 
  overflow: hidden;
  transition: width 0.3s steps(5); /* Stepped transition for retro feel */
  position: relative;
  flex-shrink: 0;
  padding-right: 5px; 
  background-color: var(--background);
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.resizing * {
  pointer-events: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  padding-bottom: 110px; /* Extra space for floating retro footer */
  min-width: 220px;
  flex: 1 1 auto; 
  overflow-y: auto;
  min-height: 0; 
}

/* Custom Blocky Scrollbar */
::-webkit-scrollbar {
  width: 16px;
  height: 16px;
  background: var(--track);
}
::-webkit-scrollbar-thumb {
  background: var(--text);
  border: 2px solid var(--track);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,0.5), inset -2px -2px 0 rgba(0,0,0,0.5);
}
::-webkit-scrollbar-button {
    background: var(--border);
    height: 16px;
    width: 16px;
}

/* FLOATING FOOTER - 8-BIT STYLE */
.sidebarFooter {
  padding: 15px;
  min-width: 220px;
  flex-shrink: 0;
  background: var(--background);
  border-top: 4px solid var(--border);
  display: flex;
  gap: 10px;
}

/* Specific styles for the floating Generate button footer */
.sidebarFooter {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  background: transparent;
  border-top: none;
  pointer-events: none;
  z-index: 10;
  padding-bottom: 20px; /* Lift it up a bit */
}

.sidebarFooter button {
  pointer-events: auto;
  background: var(--accent); /* Green button */
  color: #000;
  border: 4px solid #000;
  box-shadow: 6px 6px 0px 0px rgba(0,0,0,0.5);
}
.sidebarFooter button:hover {
    background: #81C784;
}
.sidebarFooter button:active {
    box-shadow: 0 0 0 0;
    transform: translate(6px, 6px);
}

.sidebarFooter .navBack {
  background: var(--secondary); /* Orange back button */
  color: #000;
}

.modeSelector h2 {
  font-size: 14px;
  color: var(--text);
  margin-bottom: 15px;
  text-shadow: 2px 2px 0 var(--shadow-color);
}
.modeSelector.inactive {
  opacity: 0.5;
  pointer-events: none;
}

.resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 8px;
  height: 100%;
  cursor: col-resize;
  z-index: 100;
  transition: background-color 0.2s;
  background-image: radial-gradient(circle, var(--text) 20%, transparent 20%);
  background-size: 4px 4px;
}
.resizer:hover, .modeSelector.resizing .resizer {
  background-color: var(--link);
  opacity: 1;
}

.modeList {
  flex-direction: column;
  display: flex;
  gap: 12px;
}
.modeList .button {
  justify-content: flex-start;
  gap: 12px;
  transition: none;
  background: var(--surface);
  color: var(--text);
  white-space: nowrap;
  border-radius: 0;
  min-width: fit-content;
  width: 100%;
  position: relative;
  font-family: var(--font-body);
  font-size: 20px;
}
.modeList .button:not([disabled]):hover {
  background: var(--active-item-bg);
  color: #FFF;
}
.modeList .button.active {
  background: var(--primary);
  color: #FFF;
  border-color: #000;
  box-shadow: inset 4px 4px 0 rgba(0,0,0,0.2);
  transform: translate(2px, 2px); /* Start slightly depressed */
}
.modeList .button[disabled] {
  background: var(--track);
  color: var(--mid);
  box-shadow: none;
}
.modeList + textarea {
  margin-top: 15px;
}

.modeList .tooltip {
  visibility: hidden;
  width: 200px;
  background-color: var(--tooltip-bg);
  color: var(--tooltip-text);
  text-align: center;
  border: 2px solid var(--border);
  padding: 8px;
  position: absolute;
  z-index: 10;
  bottom: 125%;
  left: 50%;
  margin-left: -100px;
  opacity: 0;
  transition: none; /* No fade, instant pop */
  font-size: 16px;
  line-height: 1.2;
  white-space: normal;
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.modeList .button:hover .tooltip {
  visibility: visible;
  opacity: 1;
}

.generateButton {
  padding: 15px 20px;
  width: 100%;
  font-size: 14px;
  font-weight: bold;
}

.output {
  flex: 1;
  padding: 20px 25px;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Use a pattern for empty area */
  background-image: linear-gradient(var(--background) 1px, transparent 1px),
  linear-gradient(90deg, var(--background) 1px, transparent 1px);
  background-size: 20px 20px;
  background-position: -1px -1px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 5px;
  border-radius: 0;
  font-size: inherit;
  text-decoration: none;
  border-bottom: 2px solid var(--link);
  background: rgba(255,255,255,0.1);
}
.output .sentence {
  font-size: 22px; /* Large retro text */
  line-height: 1.5;
  display: inline;
  cursor: pointer;
  transition: none;
  border: none;
  padding: 2px 4px;
  text-align: left;
  color: inherit;
  font-family: inherit;
  box-shadow: none;
  background: transparent;
}
.output .sentence:hover {
  opacity: 1;
  background-color: var(--active-item-bg);
  color: #FFF;
}
.output .sentence.activeSentence {
  opacity: 1;
  background-color: var(--primary);
  color: #FFF;
  border: 2px solid var(--border);
  box-shadow: 4px 4px 0 var(--shadow-color);
}
.output .sentence time {
  margin-right: 12px;
  font-family: var(--font-header);
  font-size: 0.8em;
}
.output ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.output ul button {
  font-size: 20px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 15px;
  border-radius: 0;
  width: 100%;
  background: var(--surface);
  border: 2px solid var(--border);
}
.output ul button:hover {
  background: var(--background);
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow-color);
}
.output ul button.activeItem {
  background: var(--primary);
  color: #FFF;
  border: 4px solid var(--border);
  transform: translate(0,0);
  box-shadow: inset 4px 4px 0 rgba(0,0,0,0.3);
}
.output ul button p {
  font-size: 20px;
}

.output .apiError {
  color: #FFF;
  background-color: #D32F2F; /* Retro Error Red */
  padding: 15px;
  border: 4px solid #000;
  box-shadow: 6px 6px 0 #000;
  font-family: var(--font-header);
  font-size: 12px;
  line-height: 1.5;
}

.output .textResponse {
  white-space: pre-wrap;
  line-height: 1.6;
  font-size: 20px;
}

.modeEmojis .sentence {
  font-size: 40px;
  margin-right: 20px;
}
.modeEmojis .sentence time {
  top: -8px;
}

.modeHaiku .sentence {
  display: block;
  font-size: 24px;
  margin-bottom: 10px;
  border-left: 4px solid var(--accent);
  padding-left: 10px;
}
.modeHaiku .sentence time {
  top: -5px;
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: 4px solid var(--border);
}
.modeTable th {
  text-align: left;
  background: var(--primary);
  color: #FFF;
  font-family: var(--font-header);
  font-size: 12px;
  border-bottom: 4px solid var(--border);
  border-right: 2px solid var(--border);
}
.modeTable th, .modeTable td {
  padding: 12px;
}
.modeTable td {
    border-right: 2px solid var(--border);
    border-bottom: 2px solid var(--border);
}
.modeTable tr.activeRow {
  background-color: var(--active-item-bg);
  color: #FFF;
  outline: 4px solid var(--secondary);
  outline-offset: -4px;
}

.modelSelector {
  position: relative;
  margin-bottom: 10px;
}
.modelSelector::after {
  content: "▼";
  display: block;
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  font-size: 12px;
}
.modelSelector select {
  width: 100%;
  appearance: none;
  color: var(--text);
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: 0;
  padding: 10px;
  font-family: var(--font-body);
  outline: none;
  box-shadow: 4px 4px 0 var(--shadow-color);
  cursor: pointer;
}
.modelSelector select:active {
    box-shadow: 2px 2px 0 var(--shadow-color);
    transform: translate(2px, 2px);
}

.loading {
  display: flex;
  align-items: center;
  gap: 15px;
  font-family: var(--font-header);
  font-size: 12px;
  padding: 20px;
  background: var(--surface);
  border: 4px solid var(--border);
}

/* Pixelated Spinner */
.spinner {
  width: 30px;
  height: 30px;
  background: var(--primary);
  border: none;
  animation: blink 0.5s steps(2) infinite;
  box-shadow: 4px 4px 0 var(--shadow-color);
}

@keyframes blink {
  0% { opacity: 1; }
  50% { opacity: 0; }
}

.cancelButton {
  border: 2px solid var(--border);
  padding: 5px 10px;
  border-radius: 0;
  background: var(--secondary);
  color: #000;
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: 2px solid var(--border);
  background: var(--surface);
  box-shadow: 4px 4px 0 var(--shadow-color);
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 4px; /* Thicker line */
  stroke-linecap: square; 
}
.lineChart circle {
  fill: var(--secondary);
  stroke: var(--border);
  stroke-width: 2px;
  shape-rendering: crispEdges; /* Pixelated circles */
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #000;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: 4px solid var(--border);

  /* CRT Monitor Look */
  border: 10px solid #333;
  border-radius: 10px; /* Slight curve for CRT bezel */
  box-shadow: inset 0 0 20px rgba(0,0,0,1);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: repeating-linear-gradient(
    45deg,
    #222,
    #222 10px,
    #333 10px,
    #333 20px
  );
}
.audioPlaceholder .icon {
    font-size: 80px;
    color: var(--primary);
    text-shadow: 4px 4px 0 #000;
}

.emptyVideo {
  min-height: 50vh;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  width: 100%;
  font-family: var(--font-header);
}
.uploadLabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  cursor: pointer;
  width: 100%;
  height: 100%;
  padding: 20px;
}
.emptyVideo .icon {
  font-size: 64px;
  color: var(--secondary);
  text-shadow: 4px 4px 0 #000;
  animation: bounce 1s infinite alternate;
}
@keyframes bounce {
    from { transform: translateY(0); }
    to { transform: translateY(-10px); }
}

.emptyVideo p {
  max-width: 500px;
  text-align: center;
  line-height: 1.5;
}
.emptyVideo p.error {
    color: #FFF;
    background-color: #D32F2F;
    padding: 20px;
    border: 4px solid #FFF;
    box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
}

.uploadProgress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  width: 100%;
  max-width: 300px;
  color: #fff;
  cursor: default;
  padding: 20px;
  border: 4px solid var(--border);
  background: var(--surface);
  color: var(--text);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
}

.progressBar {
  width: 100%;
  height: 20px;
  background-color: var(--track);
  border: 2px solid var(--border);
  border-radius: 0;
  overflow: hidden;
}

.progressFill {
  width: 0%;
  height: 100%;
  background-color: var(--accent); /* Retro green bar */
  transition: width 0.1s steps(10);
}

.videoCaption {
  background: #000;
  border: 2px solid #FFF;
  position: absolute;
  bottom: 80px;
  text-align: center;
  padding: 10px;
  color: #FFF;
  max-width: 720px;
  font-size: 20px;
  margin-inline: 30px;
  left: 50%;
  translate: -50% 0;
  width: -webkit-fill-available;
  border-radius: 0;
  transition: opacity 0.2s;
  z-index: 2;
  font-family: var(--font-body);
  text-shadow: 2px 2px 0 #000;
}

.videoControls {
  font-size: 12px;
  position: relative;
  background: #222; /* Darker controls */
  z-index: 3;
  border-top: 4px solid #000;
  color: #FFF;
}
.videoControls:hover .videoScrubber, .videoControls:hover .timecodeMarkerTick {
  scale: 1 1; /* Disable scale effect for strict retro feel */
}

/* Retro Scrubber */
.videoScrubber {
  height: 20px; /* Thicker */
  transform-origin: bottom;
  transition: none;
  overflow: hidden;
  background: #000;
  border-bottom: 2px solid #555;
}
.videoScrubber input {
  position: relative;
  top: -4px;
  height: 20px;
  appearance: none;
  width: 100%;
  background: transparent;
  border: none;
  box-shadow: none;
}
/* Custom range track for retro look */
.videoScrubber input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--primary) 0%, var(--primary) var(--pct), #444 var(--pct), #444 100%);
    height: 100%;
}
.videoScrubber input::-webkit-slider-thumb {
  opacity: 1; /* Visible block thumb */
  appearance: none;
  width: 10px;
  height: 20px;
  background: #FFF;
  border: 2px solid #000;
  border-radius: 0;
  cursor: col-resize;
}

.videoTime {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 15px;
  font-size: 16px;
  border-top: 2px solid #000;
  gap: 15px;
  background: #222;
  font-family: var(--font-header);
}
.videoTime button {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #FFF;
  padding: 0;
}
.videoTime button:hover {
    color: var(--primary);
    transform: none;
}
.videoTime .timeDisplay {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 20px;
}

.volumeControls {
    display: flex;
    align-items: center;
    gap: 10px;
    flex: 1;
}

.volumeSlider {
    width: 100%;
    max-width: 120px;
    height: 10px;
    accent-color: var(--primary);
    background: #000;
    border: 1px solid #555;
    box-shadow: none;
}


.timecodeList {
  overflow: auto;
  padding: 10px 20px;
}
.timecodeList td {
  padding: 10px 5px;
}
.timecodeList button {
  color: var(--link);
  box-shadow: none;
  border: none;
  background: transparent;
}
.timecodeList button:hover {
  color: var(--secondary);
  text-decoration: underline;
}

.timecodeMarkers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.timecodeMarker {
  position: absolute;
  top: 0;
  width: 4px; /* Thicker marker */
  background: rgba(255, 255, 0, 0.5); /* Yellow markers */
  translate: -2px 0;
}
.timecodeMarker:hover .timecodeMarkerLabel {
  opacity: 1;
}

.timecodeMarkerTick {
  height: 20px; /* Full height of scrubber */
  pointer-events: auto;
  cursor: pointer;
  transform-origin: bottom;
  transition: none;
  background: transparent;
  overflow: visible;
}
.timecodeMarkerTick > div {
  width: 4px;
  height: 100%;
  background: var(--secondary);
  translate: 0 0;
  border: 1px solid #000;
}

.timecodeMarkerLabel {
  background: #000;
  border: 2px solid #FFF;
  box-shadow: 4px 4px 0 rgba(0,0,0,0.5);
  opacity: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 14px;
  transition: none;
  pointer-events: none;
  position: absolute;
  top: 0;
  translate: 0 calc(-100% - 25px);
  z-index: 99;
  padding: 8px;
  border-radius: 0;
  width: max-content;
  max-width: 200px;
  color: #FFF;
  font-family: var(--font-body);
}
.timecodeMarkerLabel.right {
  right: 0;
}
.timecodeMarkerLabel p {
  color: var(--accent);
  font-size: 16px;
}

.actionToolbar {
  display: flex;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 4px solid var(--border);
  flex-wrap: wrap;
  background: var(--surface);
}

.actionButton {
  background-color: var(--surface);
  border: 2px solid var(--border);
  padding: 10px 15px;
  border-radius: 0;
  transition: none;
  font-family: var(--font-header);
  font-size: 10px;
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.actionButton:hover {
  background-color: var(--background);
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.actionButton:active {
    transform: translate(4px, 4px);
    box-shadow: none;
}

.copyButtonContainer {
  position: relative;
  display: flex;
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.copyButton {
  background-color: var(--surface);
  border: 2px solid var(--border);
  padding: 10px 15px;
  border-radius: 0;
  transition: none;
  box-shadow: none; /* Shadow handled by container */
  margin: 0;
  font-family: var(--font-header);
  font-size: 10px;
}

.copyButton.copied {
  background-color: var(--accent);
  color: #000;
}
.dark .copyButton.copied {
  background-color: var(--accent);
}

.copyDropdownButton {
  background-color: var(--surface);
  border: 2px solid var(--border);
  border-left: none;
  padding: 10px;
  border-radius: 0;
  transition: none;
  box-shadow: none;
  margin: 0;
}

.copyButton:hover,
.copyDropdownButton:hover {
  background-color: var(--background);
}
.copyButtonContainer:active {
    transform: translate(4px, 4px);
    box-shadow: none;
}

.copyDropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 5px;
  background-color: var(--surface);
  border: 2px solid var(--border);
  border-radius: 0;
  box-shadow: 4px 4px 0 var(--shadow-color);
  z-index: 10;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.copyDropdown button {
  padding: 15px;
  text-align: left;
  width: 100%;
  white-space: nowrap;
  border: none;
  border-bottom: 2px solid var(--border);
  box-shadow: none;
  font-family: var(--font-body);
  font-size: 18px;
}
.copyDropdown button:last-child {
    border-bottom: none;
}

.copyDropdown button:hover {
  background-color: var(--active-item-bg);
  color: #FFF;
}


/* Responsive Styles */
@media (max-width: 800px) {
  main {
    height: auto;
    overflow: auto;
  }
  .contentWrapper {
    height: auto;
    overflow: visible;
    border: none;
  }
  .top {
    flex-direction: column;
    height: auto; /* Reset fixed height for mobile */
    min-height: 0;
    border-bottom: 4px solid var(--border);
  }
  .modeSelector {
    width: 100% !important; /* Force width on mobile */
    border-right: none;
    border-bottom: 4px solid var(--border);
  }
  .resizer {
    display: none; /* Hide resizer on mobile */
  }
  .modeSelector.hide + .collapseButton {
    display: none;
  }
  .collapseButton {
    display: none;
  }
  .videoPlayer {
    border-left: none;
    min-height: 300px;
    border: none;
    border-bottom: 4px solid var(--border);
  }
  video {
    max-height: 60vh;
  }
  .emptyVideo {
    min-height: 300px;
  }
  .output {
    min-height: 300px;
  }
}

@charset "UTF-8";

/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
  --tooltip-bg: #E0E0E0;
  --tooltip-text: #121212;
  --active-item-bg: #283593;
  --shadow-color: rgba(0, 0, 0, 0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;

  /* Modern Retro Constants */
  --radius: 6px; /* Softens the blockiness */
  --border-width: 2px; /* Lighter borders */
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; 
  background-color: var(--background);
  color: var(--text);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 1.4;
  font-size: 14px; /* Reduced for better sizing */
}

li {
  list-style: none;
}

/* MODERN RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  outline: none;
  font-size: 20px;
  resize: none;
  user-select: text;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.15s ease;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.5;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 12px;
  margin-bottom: 15px;
}

textarea:focus, input:focus {
  border-color: var(--primary);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
}

[role=button] {
  cursor: pointer;
}

/* MODERN RETRO BUTTONS */
button {
  font-family: var(--font-body); /* Switch to body font for cleaner UI */
  font-size: 20px; /* Readable size */
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  padding: 6px 12px;
}

button:hover:not([disabled]) {
  transform: translateY(-1px);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
  background: var(--highlight);
}

button:active:not([disabled]) {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  background: var(--track);
  border-color: transparent;
}

button .icon {
  display: block;
}

.button {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

/* ICONS */
.icon {
  font-family: "Material Symbols Outlined";
  font-weight: normal;
  line-height: 1;
  font-size: 22px;
}

/* MAIN LAYOUT */
main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
}

.contentWrapper {
  max-width: 1400px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
  background: var(--background);
}

.top {
  display: flex;
  height: 50%; 
  border-bottom: var(--border-width) solid var(--border);
  background: var(--surface);
}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
  background-color: var(--surface);
}
.tools.inactive {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(100%);
}

.collapseButton {
  border: none;
  border-left: var(--border-width) solid var(--border);
  width: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  color: var(--text);
  box-shadow: none;
  border-radius: 0;
}
.collapseButton:hover {
    background: var(--active-item-bg);
}

.modeSelector {
  display: flex;
  flex-direction: column;
  gap: 0; 
  overflow: hidden;
  transition: width 0.3s ease;
  position: relative;
  flex-shrink: 0;
  padding-right: 4px; 
  background-color: var(--surface);
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  padding-bottom: 100px; /* Extra space for floating footer */
  min-width: 220px;
  flex: 1 1 auto; 
  overflow-y: auto;
  min-height: 0; 
}

/* Custom Scrollbar - Cleaner */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 5px;
  border: 2px solid var(--surface);
}
::-webkit-scrollbar-thumb:hover {
    background: var(--mid);
}

/* FLOATING FOOTER - Modern Retro */
.sidebarFooter {
  padding: 15px;
  min-width: 220px;
  flex-shrink: 0;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  background: linear-gradient(to bottom, transparent 0%, var(--surface) 40%);
  border-top: none;
  pointer-events: none;
  z-index: 10;
  padding-bottom: 20px;
}

.sidebarFooter button {
  pointer-events: auto;
  background: var(--accent); 
  color: #000; /* Contrast text */
  border: var(--border-width) solid var(--border);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1), 2px 2px 0 var(--border);
  font-weight: bold;
}
.sidebarFooter button:hover:not([disabled]) {
    transform: translateY(-2px);
    box-shadow: 0 6px 8px rgba(0,0,0,0.15), 2px 2px 0 var(--border);
}
.sidebarFooter .navBack {
  background: var(--surface);
  color: var(--text);
}

.modeSelector h2 {
  font-size: 12px;
  color: var(--mid);
  margin-bottom: 12px;
  font-family: var(--font-header);
}

.resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  z-index: 100;
  transition: background-color 0.2s;
  background: transparent;
}
.resizer:hover, .modeSelector.resizing .resizer {
  background-color: var(--primary);
  opacity: 0.5;
}

.modeList {
  flex-direction: column;
  display: flex;
  gap: 8px;
}
.modeList .button {
  justify-content: flex-start;
  gap: 12px;
  background: transparent;
  color: var(--text);
  white-space: nowrap;
  border: 1px solid transparent;
  min-width: fit-content;
  width: 100%;
  position: relative;
  font-size: 20px;
  box-shadow: none;
  border-radius: var(--radius);
  padding: 10px;
}
.modeList .button:not([disabled]):hover {
  background: var(--active-item-bg);
  border-color: var(--track);
  box-shadow: none;
  transform: none;
}
.modeList .button.active {
  background: var(--primary);
  color: #FFF;
  border-color: var(--border);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.modeList .button .emoji {
    font-size: 20px;
}

.modeList .tooltip {
  visibility: hidden;
  width: 220px;
  background-color: var(--tooltip-bg);
  color: var(--tooltip-text);
  text-align: center;
  border: var(--border-width) solid var(--border);
  padding: 10px;
  position: absolute;
  z-index: 10;
  bottom: 125%;
  left: 50%;
  margin-left: -110px;
  opacity: 0;
  transition: opacity 0.2s;
  font-size: 16px;
  line-height: 1.3;
  white-space: normal;
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.modeList .button:hover .tooltip {
  visibility: visible;
  opacity: 1;
}

.generateButton {
  padding: 14px 20px;
  width: 100%;
  font-size: 18px;
  font-family: var(--font-header);
}

.output {
  flex: 1;
  padding: 25px 30px;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Subtle dot pattern for texture */
  background-image: radial-gradient(var(--track) 1px, transparent 1px);
  background-size: 20px 20px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
  text-decoration: none;
  background: rgba(0,0,0,0.05);
  font-family: var(--font-body);
  border: 1px solid rgba(0,0,0,0.1);
}
.output .sentence {
  font-size: 22px; 
  line-height: 1.6;
  display: inline;
  cursor: pointer;
  transition: all 0.1s;
  border: 1px solid transparent;
  padding: 4px 6px;
  text-align: left;
  color: inherit;
  font-family: inherit;
  background: transparent;
  border-radius: 6px;
  margin: 0 2px;
}
.output .sentence:hover {
  opacity: 1;
  background-color: var(--active-item-bg);
}
.output .sentence.activeSentence {
  opacity: 1;
  background-color: var(--highlight);
  border: var(--border-width) solid var(--primary);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.output .sentence time {
  margin-right: 10px;
}
.output ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.output ul button {
  font-size: 20px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 16px;
  border-radius: var(--radius);
  width: 100%;
  background: var(--highlight);
  border: 1px solid var(--track);
  box-shadow: 2px 2px 0 var(--shadow-color);
  transition: all 0.1s;
}
.output ul button:hover {
  transform: translateY(-2px);
  box-shadow: 3px 3px 0 var(--shadow-color);
  border-color: var(--primary);
}
.output ul button.activeItem {
  background: var(--active-item-bg);
  border: 2px solid var(--primary);
  box-shadow: inset 0 0 0 1px var(--primary);
}
.output ul button p {
  font-size: 20px;
}

.output .apiError {
  color: #FFF;
  background-color: #EF5350;
  padding: 20px;
  border-radius: var(--radius);
  border: var(--border-width) solid #C62828;
  box-shadow: 4px 4px 0 rgba(198, 40, 40, 0.4);
  font-family: var(--font-body);
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.output .textResponse {
  white-space: pre-wrap;
  line-height: 1.6;
  font-size: 20px;
}

.modeEmojis .sentence {
  font-size: 40px;
  margin-right: 20px;
}
.modeEmojis .sentence time {
  top: -8px;
}

.modeHaiku .sentence {
  display: block;
  font-size: 24px;
  margin-bottom: 15px;
  border-left: 4px solid var(--accent);
  padding-left: 15px;
  background: var(--highlight);
  padding: 15px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 3px 3px 0 var(--shadow-color);
  background: var(--highlight);
}
.modeTable th {
  text-align: left;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-header);
  font-size: 12px;
  padding: 15px;
  border-bottom: var(--border-width) solid var(--border);
  border-right: 1px solid var(--track);
}
.modeTable th:last-child {
    border-right: none;
}
.modeTable td {
  padding: 15px;
  border-bottom: 1px solid var(--track);
  border-right: 1px solid var(--track);
}
.modeTable td:last-child {
    border-right: none;
}
.modeTable tr:last-child td {
    border-bottom: none;
}
.modeTable tr.activeRow td {
  background-color: var(--active-item-bg);
}

.modelSelector {
  position: relative;
  margin-bottom: 10px;
}
.modelSelector::after {
  content: "▼";
  display: block;
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  font-size: 12px;
}
.modelSelector select {
  width: 100%;
  appearance: none;
  color: var(--text);
  background: var(--surface);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  padding: 10px;
  font-family: var(--font-body);
  outline: none;
  box-shadow: 2px 2px 0 var(--shadow-color);
  cursor: pointer;
}

.loading {
  display: flex;
  align-items: center;
  gap: 20px;
  font-family: var(--font-body);
  font-size: 20px;
  padding: 30px;
  background: var(--highlight);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  justify-content: center;
}

/* Spinner - Less glitchy, more smooth retro */
.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--track);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.cancelButton {
  border: var(--border-width) solid var(--border);
  padding: 6px 12px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 16px;
}
.cancelButton:hover {
    background: var(--background);
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: var(--border-width) solid var(--border);
  background: var(--highlight);
  box-shadow: 4px 4px 0 var(--shadow-color);
  border-radius: var(--radius);
  padding: 10px;
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3px; 
  stroke-linecap: round; 
  stroke-linejoin: round;
}
.lineChart circle {
  fill: var(--surface);
  stroke: var(--secondary);
  stroke-width: 2px;
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 14px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #111;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: var(--border-width) solid var(--border);

  /* Modern Monitor Look - Cleaner than CRT */
  border: 4px solid #222;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
  border-radius: 4px 4px 0 0;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle, #333 0%, #111 100%);
}
.audioPlaceholder .icon {
    font-size: 80px;
    color: var(--primary);
    opacity: 0.5;
}

.emptyVideo {
  min-height: 50vh;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  width: 100%;
  font-family: var(--font-body);
}
.uploadLabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  cursor: pointer;
  width: 100%;
  height: 100%;
  padding: 20px;
}
.emptyVideo .icon {
  font-size: 64px;
  color: var(--secondary);
  margin-bottom: 10px;
}

.emptyVideo p {
  max-width: 500px;
  text-align: center;
  line-height: 1.5;
}
.emptyVideo p.error {
    color: #FFF;
    background-color: #EF5350;
    padding: 15px 25px;
    border-radius: var(--radius);
    box-shadow: 0 4px 8px rgba(0,0,0,0.2);
}

.uploadProgress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  width: 100%;
  max-width: 300px;
  color: #fff;
  cursor: default;
  padding: 30px;
  border: var(--border-width) solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.progressBar {
  width: 100%;
  height: 12px;
  background-color: var(--track);
  border-radius: 6px;
  overflow: hidden;
}

.progressFill {
  width: 0%;
  height: 100%;
  background-color: var(--accent);
  transition: width 0.3s ease;
  border-radius: 6px;
}

.videoCaption {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  position: absolute;
  bottom: 80px;
  text-align: center;
  padding: 12px 20px;
  color: #FFF;
  max-width: 720px;
  font-size: 22px;
  margin-inline: 30px;
  left: 50%;
  translate: -50% 0;
  width: -webkit-fill-available;
  border-radius: 8px;
  transition: opacity 0.2s;
  z-index: 2;
  font-family: var(--font-body);
  text-shadow: 1px 1px 0 #000;
  border: 1px solid rgba(255,255,255,0.2);
}

.videoControls {
  font-size: 12px;
  position: relative;
  background: #222; /* Darker controls */
  z-index: 3;
  color: #FFF;
  border-radius: 0 0 4px 4px;
}

/* Modern Retro Scrubber */
.videoScrubber {
  height: 12px; 
  transform-origin: bottom;
  transition: none;
  overflow: hidden;
  background: #333;
  cursor: pointer;
}
.videoScrubber:hover {
    height: 16px;
}
.videoScrubber input {
  position: relative;
  top: -6px;
  height: 20px;
  appearance: none;
  width: 100%;
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
}
/* Custom range track for retro look */
.videoScrubber input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--primary) 0%, var(--primary) var(--pct), #555 var(--pct), #555 100%);
    height: 100%;
}
.videoScrubber input::-webkit-slider-thumb {
  opacity: 0;
}

.videoTime {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  font-size: 16px;
  border-top: 1px solid #333;
  gap: 20px;
  background: #222;
  font-family: var(--font-header);
}
.videoTime button {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #AAA;
  padding: 0;
  transition: color 0.1s;
}
.videoTime button:hover {
    color: #FFF;
    transform: none;
    background: transparent;
}
.videoTime .timeDisplay {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 20px;
  color: #DDD;
}

.volumeControls {
    display: flex;
    align-items: center;
    gap: 15px;
    flex: 1;
}

.volumeSlider {
    width: 100%;
    max-width: 120px;
    height: 6px;
    accent-color: var(--primary);
    background: #444;
    border: none;
    box-shadow: none;
    border-radius: 3px;
}


.timecodeList {
  overflow: auto;
  padding: 10px 20px;
}
.timecodeList td {
  padding: 10px 5px;
}
.timecodeList button {
  color: var(--link);
  box-shadow: none;
  border: none;
  background: transparent;
}
.timecodeList button:hover {
  color: var(--secondary);
  text-decoration: underline;
}

.timecodeMarkers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.timecodeMarker {
  position: absolute;
  top: 0;
  width: 2px;
  background: rgba(255, 255, 255, 0.5); 
  translate: -1px 0;
  z-index: 4;
}
.timecodeMarker:hover {
    width: 4px;
    background: var(--accent);
    translate: -2px 0;
    z-index: 5;
}
.timecodeMarker:hover .timecodeMarkerLabel {
  opacity: 1;
}

.timecodeMarkerTick {
  height: 12px;
  pointer-events: auto;
  cursor: pointer;
  background: transparent;
}

.timecodeMarkerLabel {
  background: #222;
  border: 1px solid #555;
  box-shadow: 0 4px 8px rgba(0,0,0,0.5);
  opacity: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 14px;
  transition: opacity 0.1s;
  pointer-events: none;
  position: absolute;
  top: 0;
  translate: 0 calc(-100% - 20px);
  z-index: 99;
  padding: 8px 12px;
  border-radius: 6px;
  width: max-content;
  max-width: 240px;
  color: #EEE;
  font-family: var(--font-body);
}
.timecodeMarkerLabel.right {
  right: 0;
}
.timecodeMarkerLabel p {
  color: var(--accent);
  font-size: 16px;
}

.actionToolbar {
  display: flex;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 2px solid var(--track);
  flex-wrap: wrap;
  background: var(--surface);
  margin-bottom: 10px;
}

.actionButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius);
  transition: all 0.1s;
  font-family: var(--font-header);
  font-size: 11px;
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.actionButton:hover {
  background-color: var(--highlight);
  transform: translateY(-1px);
  box-shadow: 3px 3px 0 var(--shadow-color);
}

.copyButtonContainer {
  position: relative;
  display: flex;
  box-shadow: 2px 2px 0 var(--shadow-color);
  border-radius: var(--radius);
}

.copyButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius) 0 0 var(--radius);
  transition: none;
  box-shadow: none; 
  margin: 0;
  font-family: var(--font-header);
  font-size: 11px;
}

.copyButton.copied {
  background-color: var(--accent);
  color: #000;
}
.dark .copyButton.copied {
  background-color: var(--accent);
}

.copyDropdownButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-left: none;
  padding: 8px;
  border-radius: 0 var(--radius) var(--radius) 0;
  transition: none;
  box-shadow: none;
  margin: 0;
}

.copyButton:hover,
.copyDropdownButton:hover {
  background-color: var(--highlight);
}

.copyDropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 6px;
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  z-index: 10;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.copyDropdown button {
  padding: 12px 16px;
  text-align: left;
  width: 100%;
  white-space: nowrap;
  border: none;
  border-bottom: 1px solid var(--track);
  box-shadow: none;
  font-family: var(--font-body);
  font-size: 18px;
  border-radius: 0;
}
.copyDropdown button:last-child {
    border-bottom: none;
}

.copyDropdown button:hover {
  background-color: var(--active-item-bg);
}


/* Responsive Styles */
@media (max-width: 800px) {
  main {
    height: auto;
    overflow: auto;
  }
  .contentWrapper {
    height: auto;
    overflow: visible;
    border: none;
  }
  .top {
    flex-direction: column;
    height: auto; 
    min-height: 0;
    border-bottom: var(--border-width) solid var(--border);
  }
  .modeSelector {
    width: 100% !important; 
    border-right: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  .resizer {
    display: none; 
  }
  .modeSelector.hide + .collapseButton {
    display: none;
  }
  .collapseButton {
    display: none;
  }
  .videoPlayer {
    border-left: none;
    min-height: 300px;
    border: none;
    border-radius: 0;
    box-shadow: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  video {
    max-height: 60vh;
  }
  .emptyVideo {
    min-height: 300px;
  }
  .output {
    min-height: 300px;
  }
}

@charset "UTF-8";

/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
  --tooltip-bg: #E0E0E0;
  --tooltip-text: #121212;
  --active-item-bg: #283593;
  --shadow-color: rgba(0, 0, 0, 0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;

  /* Modern Retro Constants */
  --radius: 6px; /* Softens the blockiness */
  --border-width: 2px; /* Lighter borders */
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; 
  background-color: var(--background);
  color: var(--text);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 1.4;
  font-size: 14px; /* Reduced for better sizing */
}

li {
  list-style: none;
}

/* MODERN RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  outline: none;
  font-size: 20px;
  resize: none;
  user-select: text;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.15s ease;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.5;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 12px;
  margin-bottom: 15px;
}

textarea:focus, input:focus {
  border-color: var(--primary);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
}

[role=button] {
  cursor: pointer;
}

/* MODERN RETRO BUTTONS */
button {
  font-family: var(--font-body); /* Switch to body font for cleaner UI */
  font-size: 20px; /* Readable size */
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  padding: 6px 12px;
}

button:hover:not([disabled]) {
  transform: translateY(-1px);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
  background: var(--highlight);
}

button:active:not([disabled]) {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  background: var(--track);
  border-color: transparent;
}

button .icon {
  display: block;
}

.button {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

/* ICONS */
.icon {
  font-family: "Material Symbols Outlined";
  font-weight: normal;
  line-height: 1;
  font-size: 22px;
}

/* MAIN LAYOUT */
main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
}

.contentWrapper {
  max-width: 1400px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
  background: var(--background);
}

.top {
  display: flex;
  height: 50%; 
  border-bottom: var(--border-width) solid var(--border);
  background: var(--surface);
}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
  background-color: var(--surface);
}
.tools.inactive {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(100%);
}

.collapseButton {
  border: none;
  border-left: var(--border-width) solid var(--border);
  width: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  color: var(--text);
  box-shadow: none;
  border-radius: 0;
}
.collapseButton:hover {
    background: var(--active-item-bg);
}

.modeSelector {
  display: flex;
  flex-direction: column;
  gap: 0; 
  overflow: hidden;
  transition: width 0.3s ease;
  position: relative;
  flex-shrink: 0;
  padding-right: 4px; 
  background-color: var(--surface);
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  padding-bottom: 100px; /* Extra space for floating footer */
  min-width: 220px;
  flex: 1 1 auto; 
  overflow-y: auto;
  min-height: 0; 
  /* Push content to bottom */
  display: flex;
  flex-direction: column;
}
.sidebarContent > :first-child {
  margin-top: auto;
}

/* Custom Scrollbar - Cleaner */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 5px;
  border: 2px solid var(--surface);
}
::-webkit-scrollbar-thumb:hover {
    background: var(--mid);
}

/* FLOATING FOOTER - Modern Retro */
.sidebarFooter {
  padding: 15px;
  min-width: 220px;
  flex-shrink: 0;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  background: linear-gradient(to bottom, transparent 0%, var(--surface) 40%);
  border-top: none;
  pointer-events: none;
  z-index: 10;
  padding-bottom: 20px;
}

.sidebarFooter button {
  pointer-events: auto;
  background: var(--accent); 
  color: #000; /* Contrast text */
  border: var(--border-width) solid var(--border);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1), 2px 2px 0 var(--border);
  font-weight: bold;
}
.sidebarFooter button:hover:not([disabled]) {
    transform: translateY(-2px);
    box-shadow: 0 6px 8px rgba(0,0,0,0.15), 2px 2px 0 var(--border);
}
.sidebarFooter .navBack {
  background: var(--surface);
  color: var(--text);
}

.modeSelector h2 {
  font-size: 12px;
  color: var(--mid);
  margin-bottom: 12px;
  font-family: var(--font-header);
}

.resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  z-index: 100;
  transition: background-color 0.2s;
  background: transparent;
}
.resizer:hover, .modeSelector.resizing .resizer {
  background-color: var(--primary);
  opacity: 0.5;
}

.modeList {
  flex-direction: column;
  display: flex;
  gap: 8px;
}
.modeList .button {
  justify-content: flex-start;
  gap: 12px;
  background: transparent;
  color: var(--text);
  white-space: nowrap;
  border: 1px solid transparent;
  min-width: fit-content;
  width: 100%;
  position: relative;
  font-size: 20px;
  box-shadow: none;
  border-radius: var(--radius);
  padding: 10px;
}
.modeList .button:not([disabled]):hover {
  background: var(--active-item-bg);
  border-color: var(--track);
  box-shadow: none;
  transform: none;
}
.modeList .button.active {
  background: var(--primary);
  color: #FFF;
  border-color: var(--border);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.modeList .button .emoji {
    font-size: 20px;
}

.modeList .tooltip {
  visibility: hidden;
  width: 220px;
  background-color: var(--tooltip-bg);
  color: var(--tooltip-text);
  text-align: center;
  border: var(--border-width) solid var(--border);
  padding: 10px;
  position: absolute;
  z-index: 10;
  bottom: 125%;
  left: 50%;
  margin-left: -110px;
  opacity: 0;
  transition: opacity 0.2s;
  font-size: 16px;
  line-height: 1.3;
  white-space: normal;
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.modeList .button:hover .tooltip {
  visibility: visible;
  opacity: 1;
}

.generateButton {
  padding: 14px 20px;
  width: 100%;
  font-size: 18px;
  font-family: var(--font-header);
}

.output {
  flex: 1;
  padding: 25px 30px;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Subtle dot pattern for texture */
  background-image: radial-gradient(var(--track) 1px, transparent 1px);
  background-size: 20px 20px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
  text-decoration: none;
  background: rgba(0,0,0,0.05);
  font-family: var(--font-body);
  border: 1px solid rgba(0,0,0,0.1);
}
.output .sentence {
  font-size: 22px; 
  line-height: 1.6;
  display: inline;
  cursor: pointer;
  transition: all 0.1s;
  border: 1px solid transparent;
  padding: 4px 6px;
  text-align: left;
  color: inherit;
  font-family: inherit;
  background: transparent;
  border-radius: 6px;
  margin: 0 2px;
}
.output .sentence:hover {
  opacity: 1;
  background-color: var(--active-item-bg);
}
.output .sentence.activeSentence {
  opacity: 1;
  background-color: var(--highlight);
  border: var(--border-width) solid var(--primary);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.output .sentence time {
  margin-right: 10px;
}
.output ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.output ul button {
  font-size: 20px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 16px;
  border-radius: var(--radius);
  width: 100%;
  background: var(--highlight);
  border: 1px solid var(--track);
  box-shadow: 2px 2px 0 var(--shadow-color);
  transition: all 0.1s;
}
.output ul button:hover {
  transform: translateY(-2px);
  box-shadow: 3px 3px 0 var(--shadow-color);
  border-color: var(--primary);
}
.output ul button.activeItem {
  background: var(--active-item-bg);
  border: 2px solid var(--primary);
  box-shadow: inset 0 0 0 1px var(--primary);
}
.output ul button p {
  font-size: 20px;
}

.output .apiError {
  color: #FFF;
  background-color: #EF5350;
  padding: 20px;
  border-radius: var(--radius);
  border: var(--border-width) solid #C62828;
  box-shadow: 4px 4px 0 rgba(198, 40, 40, 0.4);
  font-family: var(--font-body);
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.output .textResponse {
  white-space: pre-wrap;
  line-height: 1.6;
  font-size: 20px;
}

.modeEmojis .sentence {
  font-size: 40px;
  margin-right: 20px;
}
.modeEmojis .sentence time {
  top: -8px;
}

.modeHaiku .sentence {
  display: block;
  font-size: 24px;
  margin-bottom: 15px;
  border-left: 4px solid var(--accent);
  padding-left: 15px;
  background: var(--highlight);
  padding: 15px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 3px 3px 0 var(--shadow-color);
  background: var(--highlight);
}
.modeTable th {
  text-align: left;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-header);
  font-size: 12px;
  padding: 15px;
  border-bottom: var(--border-width) solid var(--border);
  border-right: 1px solid var(--track);
}
.modeTable th:last-child {
    border-right: none;
}
.modeTable td {
  padding: 15px;
  border-bottom: 1px solid var(--track);
  border-right: 1px solid var(--track);
}
.modeTable td:last-child {
    border-right: none;
}
.modeTable tr:last-child td {
    border-bottom: none;
}
.modeTable tr.activeRow td {
  background-color: var(--active-item-bg);
}

.modelSelector {
  position: relative;
  margin-bottom: 10px;
}
.modelSelector::after {
  content: "▼";
  display: block;
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  font-size: 12px;
}
.modelSelector select {
  width: 100%;
  appearance: none;
  color: var(--text);
  background: var(--surface);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  padding: 10px;
  font-family: var(--font-body);
  outline: none;
  box-shadow: 2px 2px 0 var(--shadow-color);
  cursor: pointer;
}

.loading {
  display: flex;
  align-items: center;
  gap: 20px;
  font-family: var(--font-body);
  font-size: 20px;
  padding: 30px;
  background: var(--highlight);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  justify-content: center;
}

/* Spinner - Less glitchy, more smooth retro */
.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--track);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.cancelButton {
  border: var(--border-width) solid var(--border);
  padding: 6px 12px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 16px;
}
.cancelButton:hover {
    background: var(--background);
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: var(--border-width) solid var(--border);
  background: var(--highlight);
  box-shadow: 4px 4px 0 var(--shadow-color);
  border-radius: var(--radius);
  padding: 10px;
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3px; 
  stroke-linecap: round; 
  stroke-linejoin: round;
}
.lineChart circle {
  fill: var(--surface);
  stroke: var(--secondary);
  stroke-width: 2px;
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 14px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #111;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: var(--border-width) solid var(--border);

  /* Modern Monitor Look - Cleaner than CRT */
  border: 4px solid #222;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
  border-radius: 4px 4px 0 0;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle, #333 0%, #111 100%);
}
.audioPlaceholder .icon {
    font-size: 80px;
    color: var(--primary);
    opacity: 0.5;
}

.emptyVideo {
  min-height: 50vh;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  width: 100%;
  font-family: var(--font-body);
}
.uploadLabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  cursor: pointer;
  width: 100%;
  height: 100%;
  padding: 20px;
}
.emptyVideo .icon {
  font-size: 64px;
  color: var(--secondary);
  margin-bottom: 10px;
}

.emptyVideo p {
  max-width: 500px;
  text-align: center;
  line-height: 1.5;
}
.emptyVideo p.error {
    color: #FFF;
    background-color: #EF5350;
    padding: 15px 25px;
    border-radius: var(--radius);
    box-shadow: 0 4px 8px rgba(0,0,0,0.2);
}

.uploadProgress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  width: 100%;
  max-width: 300px;
  color: #fff;
  cursor: default;
  padding: 30px;
  border: var(--border-width) solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.progressBar {
  width: 100%;
  height: 12px;
  background-color: var(--track);
  border-radius: 6px;
  overflow: hidden;
}

.progressFill {
  width: 0%;
  height: 100%;
  background-color: var(--accent);
  transition: width 0.3s ease;
  border-radius: 6px;
}

.videoCaption {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  position: absolute;
  bottom: 80px;
  text-align: center;
  padding: 12px 20px;
  color: #FFF;
  max-width: 720px;
  font-size: 22px;
  margin-inline: 30px;
  left: 50%;
  translate: -50% 0;
  width: -webkit-fill-available;
  border-radius: 8px;
  transition: opacity 0.2s;
  z-index: 2;
  font-family: var(--font-body);
  text-shadow: 1px 1px 0 #000;
  border: 1px solid rgba(255,255,255,0.2);
}

.videoControls {
  font-size: 12px;
  position: relative;
  background: #222; /* Darker controls */
  z-index: 3;
  color: #FFF;
  border-radius: 0 0 4px 4px;
}

/* Modern Retro Scrubber */
.videoScrubber {
  height: 12px; 
  transform-origin: bottom;
  transition: none;
  overflow: hidden;
  background: #333;
  cursor: pointer;
}
.videoScrubber:hover {
    height: 16px;
}
.videoScrubber input {
  position: relative;
  top: -6px;
  height: 20px;
  appearance: none;
  width: 100%;
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
}
/* Custom range track for retro look */
.videoScrubber input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--primary) 0%, var(--primary) var(--pct), #555 var(--pct), #555 100%);
    height: 100%;
}
.videoScrubber input::-webkit-slider-thumb {
  opacity: 0;
}

.videoTime {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  font-size: 16px;
  border-top: 1px solid #333;
  gap: 20px;
  background: #222;
  font-family: var(--font-header);
}
.videoTime button {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #AAA;
  padding: 0;
  transition: color 0.1s;
}
.videoTime button:hover {
    color: #FFF;
    transform: none;
    background: transparent;
}
.videoTime .timeDisplay {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 20px;
  color: #DDD;
}

.volumeControls {
    display: flex;
    align-items: center;
    gap: 15px;
    flex: 1;
}

.volumeSlider {
    width: 100%;
    max-width: 120px;
    height: 6px;
    accent-color: var(--primary);
    background: #444;
    border: none;
    box-shadow: none;
    border-radius: 3px;
}


.timecodeList {
  overflow: auto;
  padding: 10px 20px;
}
.timecodeList td {
  padding: 10px 5px;
}
.timecodeList button {
  color: var(--link);
  box-shadow: none;
  border: none;
  background: transparent;
}
.timecodeList button:hover {
  color: var(--secondary);
  text-decoration: underline;
}

.timecodeMarkers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.timecodeMarker {
  position: absolute;
  top: 0;
  width: 2px;
  background: rgba(255, 255, 255, 0.5); 
  translate: -1px 0;
  z-index: 4;
}
.timecodeMarker:hover {
    width: 4px;
    background: var(--accent);
    translate: -2px 0;
    z-index: 5;
}
.timecodeMarker:hover .timecodeMarkerLabel {
  opacity: 1;
}

.timecodeMarkerTick {
  height: 12px;
  pointer-events: auto;
  cursor: pointer;
  background: transparent;
}

.timecodeMarkerLabel {
  background: #222;
  border: 1px solid #555;
  box-shadow: 0 4px 8px rgba(0,0,0,0.5);
  opacity: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 14px;
  transition: opacity 0.1s;
  pointer-events: none;
  position: absolute;
  top: 0;
  translate: 0 calc(-100% - 20px);
  z-index: 99;
  padding: 8px 12px;
  border-radius: 6px;
  width: max-content;
  max-width: 240px;
  color: #EEE;
  font-family: var(--font-body);
}
.timecodeMarkerLabel.right {
  right: 0;
}
.timecodeMarkerLabel p {
  color: var(--accent);
  font-size: 16px;
}

.actionToolbar {
  display: flex;
  gap: 15px;
  padding-bottom: 20px;
  border-bottom: 2px solid var(--track);
  flex-wrap: wrap;
  background: var(--surface);
  margin-bottom: 10px;
}

.actionButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius);
  transition: all 0.1s;
  font-family: var(--font-header);
  font-size: 11px;
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.actionButton:hover {
  background-color: var(--highlight);
  transform: translateY(-1px);
  box-shadow: 3px 3px 0 var(--shadow-color);
}

.copyButtonContainer {
  position: relative;
  display: flex;
  box-shadow: 2px 2px 0 var(--shadow-color);
  border-radius: var(--radius);
}

.copyButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius) 0 0 var(--radius);
  transition: none;
  box-shadow: none; 
  margin: 0;
  font-family: var(--font-header);
  font-size: 11px;
}

.copyButton.copied {
  background-color: var(--accent);
  color: #000;
}
.dark .copyButton.copied {
  background-color: var(--accent);
}

.copyDropdownButton {
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-left: none;
  padding: 8px;
  border-radius: 0 var(--radius) var(--radius) 0;
  transition: none;
  box-shadow: none;
  margin: 0;
}

.copyButton:hover,
.copyDropdownButton:hover {
  background-color: var(--highlight);
}

.copyDropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 6px;
  background-color: var(--surface);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  z-index: 10;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.copyDropdown button {
  padding: 12px 16px;
  text-align: left;
  width: 100%;
  white-space: nowrap;
  border: none;
  border-bottom: 1px solid var(--track);
  box-shadow: none;
  font-family: var(--font-body);
  font-size: 18px;
  border-radius: 0;
}
.copyDropdown button:last-child {
    border-bottom: none;
}

.copyDropdown button:hover {
  background-color: var(--active-item-bg);
}


/* Responsive Styles */
@media (max-width: 800px) {
  main {
    height: auto;
    overflow: auto;
  }
  .contentWrapper {
    height: auto;
    overflow: visible;
    border: none;
  }
  .top {
    flex-direction: column;
    height: auto; 
    min-height: 0;
    border-bottom: var(--border-width) solid var(--border);
  }
  .modeSelector {
    width: 100% !important; 
    border-right: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  .resizer {
    display: none; 
  }
  .modeSelector.hide + .collapseButton {
    display: none;
  }
  .collapseButton {
    display: none;
  }
  .videoPlayer {
    border-left: none;
    min-height: 300px;
    border: none;
    border-radius: 0;
    box-shadow: none;
    border-bottom: var(--border-width) solid var(--border);
  }
  video {
    max-height: 60vh;
  }
  .emptyVideo {
    min-height: 300px;
  }
  .output {
    min-height: 300px;
  }
}

