@charset "UTF-8";

/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
  --tooltip-bg: #E0E0E0;
  --tooltip-text: #121212;
  --active-item-bg: #283593;
  --shadow-color: rgba(0, 0, 0, 0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;

  /* Modern Retro Constants */
  --radius: 6px; /* Softens the blockiness */
  --border-width: 2px; /* Lighter borders */
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; 
  background-color: var(--background);
  color: var(--text);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 1.4;
  font-size: 14px; /* Reduced for better sizing */
}

li {
  list-style: none;
}

/* MODERN RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  outline: none;
  font-size: 20px;
  resize: none;
  user-select: text;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.15s ease;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.5;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 12px;
  margin-bottom: 15px;
}

textarea:focus, input:focus {
  border-color: var(--primary);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
}

[role=button] {
  cursor: pointer;
}

/* MODERN RETRO BUTTONS */
button {
  font-family: var(--font-body); /* Switch to body font for cleaner UI */
  font-size: 20px; /* Readable size */
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  padding: 6px 12px;
}

button:hover:not([disabled]) {
  transform: translateY(-1px);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
  background: var(--highlight);
}

button:active:not([disabled]) {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  background: var(--track);
  border-color: transparent;
}

button .icon {
  display: block;
}

.button {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

/* ICONS */
.icon {
  font-family: "Material Symbols Outlined";
  font-weight: normal;
  line-height: 1;
  font-size: 22px;
}

/* MAIN LAYOUT */
main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
}

.contentWrapper {
  max-width: 1400px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
  background: var(--background);
}

.top {
  display: flex;
  height: 50%; 
  border-bottom: var(--border-width) solid var(--border);
  background: var(--surface);
}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
  background-color: var(--surface);
}
.tools.inactive {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(100%);
}

.collapseButton {
  border: none;
  border-left: var(--border-width) solid var(--border);
  width: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  color: var(--text);
  box-shadow: none;
  border-radius: 0;
}
.collapseButton:hover {
    background: var(--active-item-bg);
}

.modeSelector {
  display: flex;
  flex-direction: column;
  gap: 0; 
  overflow: hidden;
  transition: width 0.3s ease;
  position: relative;
  flex-shrink: 0;
  padding-right: 4px; 
  background-color: var(--surface);
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  padding-bottom: 100px; /* Extra space for floating footer */
  min-width: 220px;
  flex: 1 1 auto; 
  overflow-y: auto;
  min-height: 0; 
  /* Push content to bottom */
  display: flex;
  flex-direction: column;
}

/* Push the first element to the bottom, effectively pushing the whole stack down */
.sidebarContent > :first-child {
  margin-top: auto;
}

/* Custom Scrollbar - Cleaner */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 5px;
  border: 2px solid var(--surface);
}
::-webkit-scrollbar-thumb:hover {
    background: var(--mid);
}

/* FLOATING FOOTER - Modern Retro */
.sidebarFooter {
  padding: 15px;
  min-width: 220px;
  flex-shrink: 0;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  background: linear-gradient(to bottom, transparent 0%, var(--surface) 40%);
  border-top: none;
  pointer-events: none;
  z-index: 10;
  padding-bottom: 20px;
}

.sidebarFooter button {
  pointer-events: auto;
  background: var(--accent); 
  color: #000; /* Contrast text */
  border: var(--border-width) solid var(--border);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1), 2px 2px 0 var(--border);
  font-weight: bold;
}
.sidebarFooter button:hover:not([disabled]) {
    transform: translateY(-2px);
    box-shadow: 0 6px 8px rgba(0,0,0,0.15), 2px 2px 0 var(--border);
}
.sidebarFooter .navBack {
  background: var(--surface);
  color: var(--text);
}

.modeSelector h2 {
  font-size: 12px;
  color: var(--mid);
  margin-bottom: 12px;
  font-family: var(--font-header);
}

.resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  z-index: 100;
  transition: background-color 0.2s;
  background: transparent;
}
.resizer:hover, .modeSelector.resizing .resizer {
  background-color: var(--primary);
  opacity: 0.5;
}

.modeList {
  flex-direction: column;
  display: flex;
  gap: 8px;
}
.modeList .button {
  justify-content: flex-start;
  gap: 12px;
  background: transparent;
  color: var(--text);
  white-space: nowrap;
  border: 1px solid transparent;
  min-width: fit-content;
  width: 100%;
  position: relative;
  font-size: 20px;
  box-shadow: none;
  border-radius: var(--radius);
  padding: 10px;
}
.modeList .button:not([disabled]):hover {
  background: var(--active-item-bg);
  border-color: var(--track);
  box-shadow: none;
  transform: none;
}
.modeList .button.active {
  background: var(--primary);
  color: #FFF;
  border-color: var(--border);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.modeList .button .emoji {
    font-size: 20px;
}

.modeList .tooltip {
  visibility: hidden;
  width: 220px;
  background-color: var(--tooltip-bg);
  color: var(--tooltip-text);
  text-align: center;
  border: var(--border-width) solid var(--border);
  padding: 10px;
  position: absolute;
  z-index: 10;
  bottom: 125%;
  left: 50%;
  margin-left: -110px;
  opacity: 0;
  transition: opacity 0.2s;
  font-size: 16px;
  line-height: 1.3;
  white-space: normal;
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.modeList .button:hover .tooltip {
  visibility: visible;
  opacity: 1;
}

.generateButton {
  padding: 14px 20px;
  width: 100%;
  font-size: 18px;
  font-family: var(--font-header);
}

.output {
  flex: 1;
  padding: 25px 30px;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Subtle dot pattern for texture */
  background-image: radial-gradient(var(--track) 1px, transparent 1px);
  background-size: 20px 20px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
  text-decoration: none;
