/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
