import {GoogleGenAI, HarmBlockThreshold, HarmCategory} from '@google/genai';
import functions from './functions';

export interface UploadedFile {
  uri: string;
  mimeType: string;
}

const systemInstruction = `When given a video and a query, call the relevant \
function only once with the appropriate timecodes and text for the video`;

async function generateContent(
  text: string,
  file: UploadedFile,
) {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error('API Key not configured in environment.');
  }

  const ai = new GoogleGenAI({ apiKey });

  // Use fileData with the URI for large files (videos/audio)
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {text},
        {
          fileData: {
            mimeType: file.mimeType,
            fileUri: file.uri,
          },
        },
      ],
    },
    config: {
      systemInstruction,
      temperature: 0.5,
      tools: [{functionDeclarations: functions}],
      safetySettings: [
        {
          category: HarmCategory.HARM_CATEGORY_HATE_SPEECH,
          threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH,
        },
        {
          category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT,
          threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH,
        },
        {
          category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT,
          threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH,
        },
        {
          category: HarmCategory.HARM_CATEGORY_HARASSMENT,
          threshold: HarmBlockThreshold.BLOCK_ONLY_HIGH,
        },
      ],
    },
  });

  return response;
}

async function uploadFile(
  file: File,
  onProgress: (progress: number) => void,
  onStatusChange: (status: string) => void,
): Promise<UploadedFile> {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error('API Key not configured in environment.');
  }

  const ai = new GoogleGenAI({ apiKey });

  try {
    onStatusChange('Uploading to Gemini...');
    onProgress(10);

    // 1. Upload the file to the File API
    const uploadResponse = await ai.files.upload({
      file: file,
      config: { 
        displayName: file.name,
        mimeType: file.type 
      }
    });

    onProgress(40);
    onStatusChange('Processing video...');

    // 2. Poll until the file is in the 'ACTIVE' state
    let fileState = uploadResponse.file.state;
    let currentFile = uploadResponse.file;

    while (fileState === 'PROCESSING') {
      // Wait 2 seconds before checking again
      await new Promise((resolve) => setTimeout(resolve, 2000));

      const getResponse = await ai.files.get({
        name: uploadResponse.file.name,
      });

      currentFile = getResponse.file;
      fileState = currentFile.state;

      // Increment progress artificially while waiting
      onProgress((prev: number) => Math.min(prev + 5, 90));
    }

    if (fileState === 'FAILED') {
      throw new Error('Video processing failed on Gemini servers.');
    }

    onProgress(100);
    onStatusChange('Analysis ready');

    return {
      uri: currentFile.uri,
      mimeType: currentFile.mimeType,
    };

  } catch (e) {
    onProgress(0);
    console.error(e);
    throw new Error(e instanceof Error ? e.message : 'Upload failed.');
  }
}

export {generateContent, uploadFile};

